CREATE TABLE IF NOT EXISTS schema_versions (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_elevation (token_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS secret_store (name TEXT PRIMARY KEY, ciphertext TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_mfa (user_id TEXT PRIMARY KEY REFERENCES users(id), ciphertext TEXT NOT NULL, last_counter BIGINT NOT NULL DEFAULT -1, recovery_hashes TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS auth_limits (bucket TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS cities (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL, country TEXT NOT NULL DEFAULT 'US', timezone TEXT NOT NULL, canonical_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, website TEXT NOT NULL DEFAULT '', city_ids_json TEXT NOT NULL DEFAULT '[]', funded INTEGER NOT NULL DEFAULT 0, budget_cents INTEGER NOT NULL DEFAULT 0, max_slots INTEGER NOT NULL DEFAULT 1, offer TEXT NOT NULL, renewal_terms TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, city_id TEXT NOT NULL REFERENCES cities(id), name TEXT NOT NULL, canonical_name TEXT NOT NULL, category TEXT NOT NULL, website_status TEXT NOT NULL DEFAULT 'unknown', proposed_website_status TEXT NOT NULL DEFAULT 'unknown', website_url TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'review', route TEXT NOT NULL DEFAULT 'unknown', history_note TEXT NOT NULL DEFAULT '', activity_note TEXT NOT NULL DEFAULT '', source_note TEXT NOT NULL DEFAULT '', evidence_json TEXT NOT NULL DEFAULT '[]', rights_confirmed INTEGER NOT NULL DEFAULT 0, verified_at TEXT, verified_by TEXT, excluded_reason TEXT NOT NULL DEFAULT '', research_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(city_id,canonical_name));
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY, email TEXT NOT NULL, email_key TEXT NOT NULL UNIQUE, source_url TEXT NOT NULL DEFAULT '', role_note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'unverified', verified_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entity_contacts (entity_id TEXT NOT NULL REFERENCES entities(id), contact_id TEXT NOT NULL REFERENCES contacts(id), route TEXT NOT NULL, PRIMARY KEY(entity_id,contact_id));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), contact_id TEXT NOT NULL UNIQUE REFERENCES contacts(id), kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'reserved', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (entity_id TEXT PRIMARY KEY REFERENCES entities(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), client_id TEXT NOT NULL REFERENCES clients(id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), kind TEXT NOT NULL DEFAULT 'initial', subject TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'draft', snapshot_json TEXT NOT NULL DEFAULT '{}', approval_hash TEXT, approved_by TEXT, approved_at TEXT, due_at TEXT, started_at TEXT, sent_at TEXT, provider_id TEXT, error TEXT NOT NULL DEFAULT '', unsubscribe_token TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(conversation_id,kind));
CREATE TABLE IF NOT EXISTS suppressions (id TEXT PRIMARY KEY, contact_id TEXT REFERENCES contacts(id), entity_id TEXT REFERENCES entities(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS suppressions_contact ON suppressions(contact_id);
CREATE INDEX IF NOT EXISTS suppressions_entity ON suppressions(entity_id);
CREATE TABLE IF NOT EXISTS provider_events (id TEXT PRIMARY KEY, message_id TEXT REFERENCES messages(id), contact_id TEXT REFERENCES contacts(id), event_type TEXT NOT NULL, source TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL UNIQUE REFERENCES entities(id), client_id TEXT NOT NULL REFERENCES clients(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), stage TEXT NOT NULL DEFAULT 'agreement', authorized_by TEXT NOT NULL, agreement_note TEXT NOT NULL, scope TEXT NOT NULL, domain TEXT NOT NULL DEFAULT '', public_url TEXT NOT NULL DEFAULT '', org_owns_domain INTEGER NOT NULL DEFAULT 0, content_approved INTEGER NOT NULL DEFAULT 0, approval_note TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', launched_at TEXT, renewal_date TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS directory_updates (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), directory_url TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'planned', confirmed_url TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_runs (id TEXT PRIMARY KEY, city_id TEXT NOT NULL REFERENCES cities(id), category TEXT NOT NULL, research_key TEXT NOT NULL UNIQUE, "window" TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', provider_id TEXT, request_json TEXT NOT NULL, report TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, tool_calls INTEGER NOT NULL DEFAULT 0, max_tool_calls INTEGER NOT NULL DEFAULT 80, imported_count INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, lease_until TEXT, next_run_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS research_due ON research_runs(state,next_run_at);
CREATE TABLE IF NOT EXISTS source_registry (id TEXT PRIMARY KEY, city_id TEXT REFERENCES cities(id), url TEXT NOT NULL, host TEXT NOT NULL, title TEXT NOT NULL, rights_note TEXT NOT NULL, fetch_allowed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(city_id,url));
CREATE TABLE IF NOT EXISTS source_traces (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES research_runs(id), tool TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', observation TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_created ON audit_log(created_at);
